sql.commissionManagement.getPayrollOverrideP:
select COUNT(opru.override_plan_id)
from brs.override_plan_receiving_user opru
WHERE opru.user_id = :userId ;

sql.commissionManagement.deletePlan:
DELETE
  FROM brs.commission_plan_user
  WHERE commission_plan_id = :planId;

DELETE
  FROM brs.commission_plan_source_allocation
  WHERE commission_plan_id = :planId;

DELETE
  FROM brs.commission_plan_allocation
  WHERE commission_plan_id = :planId;

 DELETE
  FROM brs.commission_plan
   WHERE id = :planId;

sql.commissionPlan.getUserDateRange:

select user_id, start_date, end_date
from brs.commission_plan_user
where id = :rowId;

sql.overridePlan.deletePlan:
DELETE
  FROM brs.override_plan_assigned_user
  WHERE override_plan_id = :planId;

DELETE
  FROM brs.override_plan_receiving_user
  WHERE override_plan_id = :planId;

DELETE
  FROM brs.override_plan_milestone_allocation
  WHERE override_plan_id = :planId;

 DELETE
  FROM brs.override_plan
   WHERE id = :planId;

sql.overridePlan.listAll:
SELECT array_to_json(array_agg(row_to_json(t))) FROM ( SELECT op.id, op.name, op.description, op.total, ops.status_type AS status, count(au.*) FILTER (WHERE au.start_date <= now() AND (end_date IS NULL OR au.end_date > now())) as "activeAssignedUsers", coalesce(( SELECT array_to_json(array_agg(row_to_json(u))) FROM ( SELECT opu.user_id as "userId", opu.allocation, u.first_name || ' ' || u.last_name AS name, u.employee_id AS "employeeId", p.position, p.id AS "positionId" FROM brs.override_plan_receiving_user opu INNER JOIN brs."user" u ON opu.user_id = u.id INNER JOIN brs.user_position up ON u.id = up.user_id INNER JOIN brs.position p ON up.position_id = p.id WHERE override_plan_id = op.id AND up.active IS TRUE AND up.primary_flag IS TRUE ) u), '[]') AS "receivingUsers", coalesce(( SELECT array_to_json(array_agg(row_to_json(u))) FROM ( SELECT opa.id, opa.user_id as "userId", u.first_name || ' ' || u.last_name AS name, u.employee_id AS "employeeId", p.position, p.id AS "positionId", opa.start_date AS "startDate", opa.end_date AS "endDate" FROM brs.override_plan_assigned_user opa INNER JOIN brs."user" u ON opa.user_id = u.id INNER JOIN brs.user_position up ON u.id = up.user_id INNER JOIN brs.position p ON up.position_id = p.id WHERE opa.override_plan_id = op.id AND up.active IS TRUE AND up.primary_flag IS TRUE
) u ), '[]') AS "assignedUsers"
FROM brs.override_plan op INNER JOIN brs.override_plan_status ops ON op.status_id = ops.id LEFT JOIN brs.override_plan_assigned_user au ON op.id = au.override_plan_id GROUP BY op.id, op.name, op.description, op.total, ops.status_type ORDER BY op.name ) t

sql.commissions.getUserDatesOnCommissionPlan:

select user_id, start_date::date, end_date::date
from brs.commission_plan_user
where user_id in (:userIds);
